   "answer": 0,
   "explain": "】主宾+对应关系。题干逻辑关系：七星瓢虫是蚜虫的天敌，瓢虫吃蚜虫。蚜虫是小麦 的天敌，蚜虫吃小麦。 A 项，黄鼬是老鼠的天敌，黄鼬吃老鼠。老鼠是玉米的天敌，老鼠吃玉米，与题干逻辑关 系一致，当选； 30 B 项，青蛙是蚊子的天敌，青蛙吃蚊子，但蚊子与高粱没关系，与题干逻辑关系不一致， 排除； C 项，蛇是鸟的天敌，蛇吃鸟，但前后位置反了，与题干逻辑关系不一致，排除； D 项，稗草影响水稻的生长，但螳螂是肉食，与稗草无关，与题干逻辑关系不一致，排 除。 故正确答案为A。",
