   "q": "自发裂变：核裂变：诱发裂变（ ）",
   "options": [
    "波浪能：太阳能：可再生能源",
    "铁路交通：现代交通：公路交通",
    "贸易逆差：贸易平衡：贸易顺差",
    "负有理数：负实数：负无理数"
   ],
   "answer": 3,
   "explain": "】种属＋矛盾。题干逻辑关系为自发裂变与诱发裂变二者为矛盾关系，都是核裂变的 一种，为种属关系。 A 项，波浪能与太阳能都是可再生能源的一种，二者为种属关系，但二者为反对关系，不 是矛盾，与题干逻辑关系不一致，排除； B 项，铁路交通与公路交通，都属于现代交通，但二者为并列关系中的反对关系，不是矛 盾，与题干逻辑关系不一致，排除； C 项，贸易逆差，贸易平衡，贸易顺差，三者为并列关系，与题干逻辑关系不一致，排除； D 项，负有理数与负无理数二者是矛盾关系，且都是负实数的一种与题干逻辑关系一致， 当选。 故正确答案为D。",
