   "module": "panduan",
   "q": "重型战机 对于（ ）相当于（ ）对于 分辨率",
   "options": [
    "轻型战机；订单量",
    "隐形战机；清晰度",
    "载弹量；显示器",
    "战斗机；性能指标这段陈述，选择一个答案。注意：正确答案应与所给的陈述相符合，不需要任何附加说~ 25 ~全国服务电话：400-6353-606明即可以从陈述中直接推出。请开始答题："
   ],
   "answer": 2,
   "explain": "】代入选项。 A 项，重型战机和轻型战机并列关系，订单量和分辨率无明显逻辑关系，前后逻辑不一 致，排除； B 项，重型战机和隐形战机交叉关系，分辨率越高清晰度越低，对应关系，前后逻辑不一 致，排除； C 项，载弹量受到重型战机承载能力的限制，分辨率受到显示器屏幕的限制，二者都是对 应关系，当选； D 项，重型战机是战斗机的一种，二者种属关系，分辨率是性能指标的一种，种属关系， 但顺序反了，前后逻辑不一致，排除。 故正确答案为C。 32",
