   "module": "changshi",
   "q": "下列关于提升贸易投资合作质量和水平的措施，表述准确的是（ ）①推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易，加快建设贸易强国②扩大外资准入负面清单，营造市场化、法制化、国际化一流营商环境③优化区域开放布局，巩固中西部和东北地区开放先导地位，提高东部地区开放水平④实施自由贸易试验区提升战略，扩大面向全球的高标准自由贸易区网络",
