   "module": "changshi",
   "q": "《黑土地保护法》自2022 年8 月1 日起施行，下列表述不符合该法规定的是（ ）",
   "options": [
    "除国防建设项目选址无法避开外，其他建设项目一律不得占用黑土地",
    "黑土层深厚、土壤性状良好的黑土地划入永久基本农田，重点用于粮食生产",
    "无法修复的黑土地不列入黑土地保护范围进行修复",
    "县级以上人民政府应当将黑土地保护工作纳入国民经济和社会发展规划"
   ],
   "answer": 0,
   "explain": "】本题考查法律常识。 A 项，根据《黑土地保护法》第二十一条：建设项目不得占用黑土地；确需占用的，应当 依法严格审批，并补充数量和质量相当的耕地。故选项表述错误； B 项，根据《黑土地保护法》第五条：黑土层深厚、土壤性状良好的黑土地应当按照规定 的标准划入永久基本农田，重点用于粮食生产，实行严格保护，确保数量和质量长 期稳定； C 项，根据《黑土地保护法》第四条：国务院农业农村主管部门会同自然资源、水行政等 有关部门，综合考虑黑土地开垦历史和利用现状，以及黑土层厚度、土壤性状、土 壤类型等，按照最有利于全面保护、综合治理和系统修复的原则，科学合理确定黑 土地保护范围并适时调整，有计划、分步骤、分类别地推进黑土地保护工作。历史 上属黑土地的，除确无法修复的外，原则上都应列入黑土地保护范围进行修恢复。 故选项表述正确； D 项，根据《黑土地保护法》第十条：县级以上人民政府应当将黑土地保护工作纳",
