   "explain": "】几何问题。要想工作站C 点与两个联络站距离之和最小，如图所示，沿路做甲的镜 ，丙，则甲 ，乙＝甲丙+丙乙。甲甲 像，甲丙= 甲 ，乙= 26km。 可知（三边比例5：12：13），甲 故正确答案为A。",
